  'rfi|SB|ace_o_big|raise': { text: '큰 오프수트 A는 수티드가 아니어도 두 장이 다 높아 탑페어를 자주 만들고, A가 BB의 AA·AK도 줄여요.', principles: ['hand-strength', 'blockers'], bookDiff: '' },
